<?php
require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/config/database.php'; checkRole(['ADMIN','PROFESSOR']); $db=getDB();$escolinha=currentEscolinhaId();$professor=hasRole(['PROFESSOR'])?(int)$_SESSION['user_id']:null;$edit=null;
function aulaDaEscolinha($db,$id,$escolinha,$professor){$sql='SELECT a.* FROM TB_AULA a JOIN TB_TURMA t ON t.COD_TURMA=a.COD_TURMA WHERE a.COD_AULA=? AND t.COD_ESCOLINHA=?';$args=[$id,$escolinha];if($professor){$sql.=' AND t.COD_PROFESSOR=?';$args[]=$professor;}$q=$db->prepare($sql);$q->execute($args);return $q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='attendance'){$aula=aulaDaEscolinha($db,$id,$escolinha,$professor);if(!$aula){flash('error','Aula não encontrada.');go('aulas.php');}$alunos=$_POST['alunos']??[];$save=$db->prepare('INSERT INTO TB_PRESENCA (COD_AULA,COD_ALUNO,PRESENTE,JUSTIFICATIVA) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE PRESENTE=VALUES(PRESENTE),JUSTIFICATIVA=VALUES(JUSTIFICATIVA)');foreach($alunos as $cod=>$dados){$save->execute([$id,(int)$cod,isset($dados['presente'])?1:0,trim($dados['justificativa']??'')?:null]);}flash('success','Chamada registrada.');go('aulas.php?chamada='.$id);}if($action==='delete'){if(aulaDaEscolinha($db,$id,$escolinha,$professor)){$db->prepare('DELETE FROM TB_AULA WHERE COD_AULA=?')->execute([$id]);flash('success','Aula excluída.');}go('aulas.php');}$turma=(int)($_POST['cod_turma']??0);$data=$_POST['data_aula']??'';$tema=trim($_POST['tema_treino']??'');$obs=trim($_POST['observacao']??'');$turmaSql='SELECT 1 FROM TB_TURMA WHERE COD_TURMA=? AND COD_ESCOLINHA=?';$args=[$turma,$escolinha];if($professor){$turmaSql.=' AND COD_PROFESSOR=?';$args[]=$professor;}$q=$db->prepare($turmaSql);$q->execute($args);if(!$q->fetchColumn()||!$data||$tema===''){flash('error','Informe turma, data e tema válidos.');go('aulas.php');}if($action==='create'){$db->prepare('INSERT INTO TB_AULA (COD_TURMA,DATA_AULA,TEMA_TREINO,OBSERVACAO) VALUES (?,?,?,?)')->execute([$turma,$data,$tema,$obs?:null]);flash('success','Aula cadastrada.');}elseif($action==='update'&&aulaDaEscolinha($db,$id,$escolinha,$professor)){$db->prepare('UPDATE TB_AULA SET COD_TURMA=?,DATA_AULA=?,TEMA_TREINO=?,OBSERVACAO=? WHERE COD_AULA=?')->execute([$turma,$data,$tema,$obs?:null,$id]);flash('success','Aula atualizada.');}go('aulas.php');}
if(isset($_GET['editar'])){$edit=aulaDaEscolinha($db,(int)$_GET['editar'],$escolinha,$professor);if(!$edit){flash('error','Aula não encontrada.');go('aulas.php');}}$sql='SELECT COD_TURMA,NOME FROM TB_TURMA WHERE COD_ESCOLINHA=? AND ATIVA=1';$args=[$escolinha];if($professor){$sql.=' AND COD_PROFESSOR=?';$args[]=$professor;}$q=$db->prepare($sql);$q->execute($args);$turmas=$q->fetchAll();
if(isset($_GET['chamada'])){$aula=aulaDaEscolinha($db,(int)$_GET['chamada'],$escolinha,$professor);if(!$aula){flash('error','Aula não encontrada.');go('aulas.php');}$q=$db->prepare("SELECT a.COD_ALUNO,a.NOME,p.PRESENTE,p.JUSTIFICATIVA FROM TB_MATRICULA m JOIN TB_ALUNO a ON a.COD_ALUNO=m.COD_ALUNO LEFT JOIN TB_PRESENCA p ON p.COD_ALUNO=a.COD_ALUNO AND p.COD_AULA=? WHERE m.COD_TURMA=? AND m.STATUS='ATIVA' ORDER BY a.NOME");$q->execute([$aula['COD_AULA'],$aula['COD_TURMA']]);$alunos=$q->fetchAll();pageStart('Chamada: '.date('d/m/Y',strtotime($aula['DATA_AULA'])));?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="attendance"><input type="hidden" name="id" value="<?=(int)$aula['COD_AULA']?>"><div><?php foreach($alunos as $a):?><div><strong><?=e($a['NOME'])?></strong><label><input type="checkbox" name="alunos[<?=(int)$a['COD_ALUNO']?>][presente]" <?=($a['PRESENTE']??1)?'checked':''?>> Presente</label><input name="alunos[<?=(int)$a['COD_ALUNO']?>][justificativa]" value="<?=e($a['JUSTIFICATIVA']??'')?>" placeholder="Justificativa da ausência"></div><?php endforeach;?></div><div><?php actionButton('Salvar chamada');?><a href="aulas.php">Voltar</a></div></form><?php pageEnd();exit;}
$sql='SELECT a.*,t.NOME AS TURMA FROM TB_AULA a JOIN TB_TURMA t ON t.COD_TURMA=a.COD_TURMA WHERE t.COD_ESCOLINHA=?';$args=[$escolinha];if($professor){$sql.=' AND t.COD_PROFESSOR=?';$args[]=$professor;}$sql.=' ORDER BY a.DATA_AULA DESC';$q=$db->prepare($sql);$q->execute($args);$lista=$q->fetchAll();pageStart('Aulas e chamada');
?><section><h2><?=$edit?'Editar aula':'Nova aula'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['COD_AULA']?>"><?php endif;?><label>Turma<select required name="cod_turma"><option value="">Selecione</option><?php foreach($turmas as $t):?><option value="<?=(int)$t['COD_TURMA']?>" <?=($edit['COD_TURMA']??'')==$t['COD_TURMA']?'selected':''?>><?=e($t['NOME'])?></option><?php endforeach;?></select></label><label>Data<input required type="date" name="data_aula" value="<?=e($edit['DATA_AULA']??date('Y-m-d'))?>"></label><label>Tema do treino<input required name="tema_treino" value="<?=e($edit['TEMA_TREINO']??'')?>"></label><label>Observação<textarea name="observacao"><?=e($edit['OBSERVACAO']??'')?></textarea></label><div><?php actionButton($edit?'Salvar alterações':'Cadastrar aula');?><?php if($edit):?><a href="aulas.php">Cancelar</a><?php endif;?></div></form></section><section><table><thead><tr><th>Data</th><th>Turma</th><th>Tema</th><th>Ações</th></tr></thead><tbody><?php foreach($lista as $a):?><tr><td><?=e(date('d/m/Y',strtotime($a['DATA_AULA'])))?></td><td><?=e($a['TURMA'])?></td><td><?=e($a['TEMA_TREINO'])?></td><td><a href="aulas.php?chamada=<?=(int)$a['COD_AULA']?>">Chamada</a><a href="aulas.php?editar=<?=(int)$a['COD_AULA']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir esta aula?');"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$a['COD_AULA']?>"><button>Excluir</button></form></td></tr><?php endforeach;?></tbody></table></section><?php pageEnd();?>
